library(creditratingsystem)
T<-list(event='default',horizon=1,time_unit='years',probability_measure='PHYSICAL',conditioning='performing');C<-list(rubric_id='synthetic',version='1',population_id='SME',reference='synthetic qualitative exercise',known_at='2024-01-01',ordered_grades=as.list(c('A','B','C','D')),score_direction='higher_is_worse',target=T);P<-list(score_floor=0,score_cap=80,minimum_evidence_coverage=0,unresolved_interaction_policy='apply_adverse');D<-list(valid_from='2024-01-01',valid_until='2025-01-01',known_at='2024-01-01')
common<-list(weight=1,required_evidence_types=list('audit'),minimum_independent_sources=1,missing_policy='worst',not_applicable_policy='refer')
criteria<-list(modifyList(common,list(criterion_id='management',kind='categorical',categories=list('strong','weak'),minimum_independent_sources=2,levels=list(list(level_id='strong',values=list('strong'),points=0),list(level_id='weak',values=list('weak'),points=100)))),modifyList(common,list(criterion_id='debt',kind='numeric',risk_order='increasing',weight=2,levels=list(list(level_id='low',lower=0,upper=2,points=20),list(level_id='stress',lower=2,upper=5,points=70),list(level_id='high',lower=5,upper=10,points=100)))),modifyList(common,list(criterion_id='permit',kind='categorical',categories=list('valid','expired'),levels=list(list(level_id='valid',values=list('valid'),points=0),list(level_id='expired',values=list('expired'),points=100)))))
interactions<-list(list(interaction_id='joint',conditions=list(management=list('weak'),debt=list('stress','high')),points_delta=15,reference='documented adverse combination'));limits<-list(list(limit_id='management-limit',conditions=list(management=list('weak')),best_allowed_grade='B',worst_allowed_grade='D',reference='rating policy'))
ev<-lapply(0:3,function(i)c(D,list(evidence_id=paste0('e',i),evidence_type='audit',source_id=paste0('source',i),independence_group=paste0('group',i),content_fingerprint=paste0('content',i),status='VERIFIED')))
obs<-list(c(D,list(observation_id='o1',criterion_id='management',value='weak',not_applicable=FALSE,evidence_ids=list('e0','e1'),observed_at='2024-01-01')),c(D,list(observation_id='o2',criterion_id='debt',value=2,not_applicable=FALSE,evidence_ids=list('e2'),observed_at='2024-01-01')),c(D,list(observation_id='o3',criterion_id='permit',value='valid',not_applicable=FALSE,evidence_ids=list('e3'),observed_at='2024-01-01')))
compile<-function(criteria)compile_qualitative_rubric(criteria,C,P,interactions,limits);evaluate<-function(r,obs,ev,...)evaluate_qualitative_evidence(r,obs,ev,as_of='2024-04-01',known_at='2024-04-01',...)$value
reject<-function(expr,code){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'error'),grepl(code,e$code,fixed=TRUE))}
r<-compile(criteria);result<-evaluate(r,obs,ev);stopifnot(result$score==75,identical(result$status,'READY'),result$evidence_coverage==1,identical(unlist(result$permitted_grade_interval),c('B','D')))
changed<-obs;changed[[2]]$value<-10;stopifnot(evaluate(r,changed,ev)$score==80);changed[[2]]$value<-10.1;stopifnot(evaluate(r,changed,ev)$status=='REFER')
stopifnot(evaluate(r,obs[-3],ev)$score>=75);future<-ev;future[[4]]$known_at<-'2024-06-01';result<-evaluate(r,obs,future);stopifnot(result$score>=75,result$evidence_coverage==.75);future[[2]]$independence_group<-future[[1]]$independence_group;result<-evaluate(r,obs,future);stopifnot(result$status=='REFER',result$evidence_coverage==.5)
contradict<-obs;new<-obs[[1]];new$observation_id<-'o4';new$value<-'strong';contradict[[4]]<-new;result<-evaluate(r,contradict,ev);stopifnot(result$status=='REFER',is.null(result$score))
conflict<-c(D,list(conflict_id='c1',observation_ids=list('o1','o4'),status='RESOLVED',resolution_observation_id='o1',reference='reviewed original records'));fixed<-evaluate(r,contradict,ev,conflicts=list(conflict));stopifnot(fixed$score==75,fixed$status=='READY');conflict$known_at<-'2024-05-01';stopifnot(evaluate(r,contradict,ev,conflicts=list(conflict))$status=='REFER')
bad<-criteria;bad[[2]]$levels[[1]]$upper<-3;reject(compile(bad),'COVERAGE');bad<-criteria;bad[[3]]$missing_policy<-'exclude';reject(compile(bad),'MISSING')
na_criteria<-criteria;na_criteria[[3]]$not_applicable_policy<-'fixed';na_criteria[[3]]$not_applicable_points<-50;r<-compile(na_criteria);na_obs<-obs;na_obs[[3]]$not_applicable<-TRUE;na_obs[[3]]['value']<-list(NULL);stopifnot(evaluate(r,na_obs,ev)$score==80);ev[[4]]$status<-'UNVERIFIED';result<-evaluate(r,na_obs,ev);stopifnot(result$criterion_results[[3]]$points==100)
